// Auto-grader for the pre-work exercises. Do not edit this file.
// Run: npm run prework
import { test, expect } from '@playwright/test';
import * as ex from './exercises';

const cart: ex.CartItem[] = [
  { name: 'Thor Hammer', price: 11.14, quantity: 1 },
  { name: 'Claw Hammer', price: 11.48, quantity: 2 },
  { name: 'Pliers', price: 12.01, quantity: 0 },
];

test.describe('part 1 — basics', () => {
  test('01 add', () => {
    expect(ex.add(2, 3)).toBe(5);
    expect(ex.add(-1, 1)).toBe(0);
  });
  test('02 fullName', () => {
    expect(ex.fullName('Jane', 'Doe')).toBe('Jane Doe');
  });
  test('03 isAdult', () => {
    expect(ex.isAdult(18)).toBe(true);
    expect(ex.isAdult(17)).toBe(false);
  });
  test('04 formatPrice', () => {
    expect(ex.formatPrice(12.5)).toBe('$12.50');
    expect(ex.formatPrice(9.169)).toBe('$9.17');
  });
  test('05 toSlug', () => {
    expect(ex.toSlug('Claw Hammer')).toBe('claw-hammer');
    expect(ex.toSlug('Long Nose Pliers')).toBe('long-nose-pliers');
  });
  test('06 cartTotal', () => {
    expect(ex.cartTotal(cart)).toBe(34.1);
    expect(ex.cartTotal([])).toBe(0);
  });
  test('07 nonEmptyItems', () => {
    expect(ex.nonEmptyItems(cart).map((i) => i.name)).toEqual(['Thor Hammer', 'Claw Hammer']);
  });
  test('08 cheapestName', () => {
    expect(ex.cheapestName(cart)).toBe('Thor Hammer');
  });
  test('09 sortedNames', () => {
    const copy = [...cart];
    expect(ex.sortedNames(cart)).toEqual(['Claw Hammer', 'Pliers', 'Thor Hammer']);
    expect(cart).toEqual(copy); // original not changed
  });
  test('10 countByCategory', () => {
    expect(ex.countByCategory([{ category: 'Hammer' }, { category: 'Pliers' }, { category: 'Hammer' }]))
      .toEqual({ Hammer: 2, Pliers: 1 });
  });
});

test.describe('part 2 — async/await @async', () => {
  test('11 productName', async () => {
    expect(await ex.productName(1)).toBe('Claw Hammer');
  });
  test('12 isInStock', async () => {
    expect(await ex.isInStock(1)).toBe(true);
    expect(await ex.isInStock(2)).toBe(false);
  });
  test('13 productNames loads in parallel', async () => {
    const start = Date.now();
    expect(await ex.productNames([3, 1, 5])).toEqual(['Combination Pliers', 'Claw Hammer', 'Wood Saw']);
    expect(Date.now() - start, 'should load all at once, not one after another').toBeLessThan(100);
  });
  test('14 safeProductName', async () => {
    expect(await ex.safeProductName(1)).toBe('Claw Hammer');
    expect(await ex.safeProductName(999)).toBe('not found');
  });
  test('15 inStockCount', async () => {
    expect(await ex.inStockCount()).toBe(3);
  });
});
